# application.yml  (el nodo deja de deducirse del número de serie del procesador)
s151.lote:
  nodo: 10                         # 10 = Valle de México, 4 = Monterrey; se fija por despliegue
  nodos-legados:                   # solo para auditoría y pruebas de equivalencia
    por-serie: { "3251": 4, "3247": 4, "866": 10, "2222": 10 }
    por-host-serie-3246: { "ACYPGAMA": 10, "VDMBETA": 10, "MONALFA": 4, "ACYPOMEGA": 10 }

// ---------------------------------------------------------------------------
@ConfigurationProperties("s151.lote")
public record LoteProperties(int nodo, NodosLegados nodosLegados /* , ... */) {

    public LoteProperties {
        if (nodo != 4 && nodo != 10) {
            // En el WFL un serial desconocido deja NODO = 0 y el job sigue; aquí no arranca.
            throw new IllegalStateException("s151.lote.nodo inválido: " + nodo);
        }
    }

    public record NodosLegados(Map<String, Integer> porSerie, Map<String, Integer> porHostSerie3246) {}
}

/** Prólogo del job: reemplaza el parseo de PARAMETRO, el menú de consola y CAMBIAVER. */
@Component
@RequiredArgsConstructor
public class LoteLauncher {

    private final JobLauncher jobLauncher;
    private final Job loteS151;
    private final VersionGate versionGate;          // VALIDAVER
    private final Clock relojMx;                    // zona America/Mexico_City

    public JobExecution lanza(String parametro) throws Exception {
        // SEPARAPARAM: AUX es el primer token y AUX1..AUX10 los siguientes.
        List<String> t = List.of(parametro.trim().split("\\s+"));
        String aux = t.get(0);
        if (Set.of("", "M", "MENU", "V", "VERSION").contains(aux)) {
            throw new JobParametersInvalidException(
                "El menú interactivo y el cambio de versión por consola no existen en el destino");
        }
        versionGate.verifica("S151LOTE");           // aborta si la versión catalogada difiere
        LocalDate fechaMaquina = LocalDate.now(relojMx);   // FECHAY := TIMEDATE(YYMMDD), sin pivote

        JobParameters params = new JobParametersBuilder()
                .addString("parametro", parametro)
                .addString("comando", aux)
                .addString("aux1", t.size() > 1 ? t.get(1) : "")
                .addString("sistpar", t.size() > 2 ? t.get(2) : "")    // SISTPAR := AUX2
                .addLocalDate("fechaMaquina", fechaMaquina)
                .toJobParameters();
        return jobLauncher.run(loteS151, params);    // JOBSUMMARYTITLE -> nombre e id de la ejecución
    }
}

/** VALIDAVER: compara la versión desplegada del orquestador contra el catálogo S006. */
@Component
@RequiredArgsConstructor
public class VersionGate {

    private final CatalogoVersionesClient catalogo;   // reemplaza RUN #S006P618
    private final BuildProperties build;              // versión del artefacto desplegado

    public void verifica(String componente) {
        String catalogada = catalogo.versionCatalogada(componente);
        if (!catalogada.equals(build.getVersion())) {
            // El WFL hace WAIT(MENSAJE, OK) y GO FIN: espera confirmación del operador y termina.
            throw new VersionNoCatalogadaException(
                "ERROR EN VERSION DEL WFL/LOTE, LA VERSION CATALOGADA ES " + catalogada);
        }
    }
}

# application.yml
s151.lote.sistemas-satelite: [S264, S500, S333, S335, S336, S403, S408, S084, S701,
                              S711, S087, S703, S404, S702, S017, S018, S502, S252]

// ---------------------------------------------------------------------------
/** CASE AUX OF: traduce el comando de arranque en la rama del DAG que se ejecuta. */
@Component
@RequiredArgsConstructor
public class ComandoLoteDecider implements JobExecutionDecider {

    private final LoteProperties props;

    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution ultimo) {
        String aux = job.getJobParameters().getString("comando");
        if ("DIARIO".equals(aux))      return new FlowExecutionStatus("DIARIO");   // PASO 1
        if ("DIARIOADMOV".equals(aux)) return new FlowExecutionStatus("ADMOV");    // PASO 50
        if (props.sistemasSatelite().contains(aux)) {
            String sistema = aux.substring(1);                     // SISTPAR := DROP(AUX,1): "084", "500"
            job.getExecutionContext().putString("sistema", sistema);
            return "584".equals(sistema)                           // PASO 72: sistema dado de baja
                    ? new FlowExecutionStatus("BAJA")
                    : new FlowExecutionStatus("SATELITE");         // PASO 72 -> PRODIASNNN
        }
        return new FlowExecutionStatus("INVALIDO");                // PASO := 9999999999
    }
}

/** CASE PASO (1) DIARIO: 12 pasos secuenciales. */
@Bean
Flow diarioFlow(LoteSteps s, NodoDecider nodo) {
    Step p000FueraDeLinea = s.p000(0);                             // VALUE000 := 0
    return new FlowBuilder<SimpleFlow>("diario")
            .start(s.p612("DAILY"))                                // aviso de inicio
            .next(s.p000(1))                                       // proyección en línea; TASKVALUE -> fecha
            .next(s.calendario())                                  // FECHAS: DIA30, DIA1MES, FESTIVO, ...
            .next(s.dumpAdSaldo(Respaldo.EN_LINEA))                // B2OLMEN si DIA30, B2OLDIA si no
            .next(s.limpiaListados("P120"))                        // REMUEVEBACKUPS(120)
            .next(nodo)
                .on("VDM").to(s.p120()).next(p000FueraDeLinea)     // SUB120 solo en nodo 10
            .from(nodo)
                .on("*").to(p000FueraDeLinea)
            .next(s.inicializaAdSaldo())                           // INICIALIZASDO
            .next(s.dumpAdSaldo(Respaldo.BATCH))                   // B2OBMEN si DIA30, B2OBDIA si no
            .next(s.limpiaListados("P005"))
            .next(s.p005())                                        // carga de archivos para Tesorería
            .next(s.p612("DDIAR"))                                 // aviso de fin
            .build();
}
// dumpAdSaldo lee la bandera DIA30 del ExecutionContext y elige la etiqueta de cinta.

/** PRODIASNNN(SNNN), primer tramo. Deciders y steps son @Bean singleton. */
@Bean
Flow prodiaSateliteInicio(LoteSteps s, SateliteDeciders d) {
    return new FlowBuilder<SimpleFlow>("prodiasnnn-inicio")
            .start(d.marcaInicio())                     // SNNN distinto de "804" y "203"
                .on("MARCA").to(s.p196(1)).next(d.esCaja500())
            .from(d.marcaInicio()).on("*").to(d.esCaja500())
            .from(d.esCaja500()).on("S500").to(s.p172())            // archivos IntelliMatch
                .next(d.nodo()).on("MTY").to(s.transfiereIntelli()) // SUB102 x2, solo nodo 04
                .next(s.lanzaP199Asincrono())
            .from(d.nodo()).on("*").to(s.lanzaP199Asincrono())
            .from(s.lanzaP199Asincrono()).on("*").to(s.p152())     // cifras BIFIN
            .from(d.esCaja500()).on("*").to(s.p152())
            .build();
}

/** PROCESS SUB199(SNNN): único paso asíncrono; el job no espera su término. */
@Bean
Step lanzaP199Asincrono(JobRepository repo, PlatformTransactionManager tx,
                        @Qualifier("asyncJobLauncher") JobLauncher async, Job p199Job) {
    return new StepBuilder("lanzaP199Asincrono", repo).tasklet((contrib, ctx) -> {
        String sistema = (String) ctx.getStepContext().getJobExecutionContext().get("sistema");
        Thread.sleep(Duration.ofSeconds(10));                       // WAIT(10) previo
        async.run(p199Job, new JobParametersBuilder()
                .addString("sistema", sistema)
                .addLong("lanzado", System.currentTimeMillis()).toJobParameters());
        Thread.sleep(Duration.ofSeconds(10));                       // WAIT(10) posterior
        return RepeatStatus.FINISHED;
    }, tx).build();
}

/** SUB001 función "00" + FECHAS + SUB178 + archivo de control corporativo del S084. */
@Bean @JobScope
Step proyeccionYControlS084(JobRepository repo, PlatformTransactionManager tx,
                            P001Client p001, P178Client p178, P312Client p312,
                            CalendarioCorporativo calendario,
                            ArchivosMcp fs, LoteProperties props,
                            @Value("#{jobExecutionContext['sistema']}") String sistema) {
    return new StepBuilder("proyeccionYControlS084", repo).tasklet((contrib, ctx) -> {
        var jctx = contrib.getStepExecution().getJobExecution().getExecutionContext();

        FechasSistema f = p001.proyecta(sistema, "00");      // FANTIER, FAYER, FHOY, FMANANA, ...
        Banderas b = calendario.banderas(f.hoy());           // FECHAS(FECHAY): DIA30, DIA1MES, ...
        LocalDate fechaY = f.manana();                       // FECHAY := DECIMAL(FMANANA)
        jctx.put("fechas", f); jctx.put("banderas", b); jctx.put("fechaY", fechaY);
        p178.ejecuta(sistema);                               // checa saldos

        if (b.dia30() && "500".equals(sistema)) {
            String destino = "S151/FILE/S084/%02d/%s".formatted(props.nodo(),
                    fechaY.format(DateTimeFormatter.ofPattern("yyMMdd")));
            switch (props.nodo()) {
                case 10 -> fs.copia("S151/FILE/CONTROL/CORP", destino, Seguridad.PUBLIC_IO);
                case 4  -> { p312.ejecuta(); fs.transfiere(destino, "CMEMP", "CMEMP"); }
                default -> throw new IllegalStateException("nodo sin rama");   // NODO 32 no existe
            }
        }
        return RepeatStatus.FINISHED;
    }, tx).build();
}

/** PRODIASNNN, tramo final: respaldos condicionados y marca de fin. */
@Bean @JobScope
Step respaldosYCierreSatelite(JobRepository repo, PlatformTransactionManager tx,
                              P197Client p197, DmsiiUtility dmsii, ArchivosMcp fs, P196Client p196,
                              @Value("#{jobExecutionContext['sistema']}") String sistema,
                              @Value("#{jobExecutionContext['banderas']}") Banderas b) {
    return new StepBuilder("respaldosYCierreSatelite", repo).tasklet((contrib, ctx) -> {
        NombresBase bases = p197.mantenimientoCiclo(sistema);   // devuelve NOMBASE11 y NOMBASE12

        if (bases.saldos().isPresent()) {
            dmsii.dumpEnLinea(bases.saldos().get(), "B11OLDI");
        }
        if (bases.ciclo().isPresent() && "500".equals(sistema)) {
            dmsii.dumpEnLinea(bases.ciclo().get(), "B12OLDI");
            dmsii.inicializa(bases.ciclo().get());               // INICIABD12MCIC
        }
        if ("500".equals(sistema) && b.dia1Mes()) {
            fs.remove("S151/FILE/S084/10/=");
            fs.remove("S151/FILE/S084/04/=");
        }
        // VALUE196 := 0: marca de fin. En el WFL corre también para 804 y 203,
        // que nunca recibieron la marca de inicio.
        p196.marcaFin(sistema, "00000000", "000", "00", "000");
        return RepeatStatus.FINISHED;
    }, tx).build();
}

/** Plantilla SUBnnn: un Step por programa COBOL con su política de reinicio y su listado. */
public Step pasoCobol(String paso, String objeto, Map<String, Object> taskValue) {
    return new StepBuilder(paso, repo)
            .tasklet(new ProgramaLegadoTasklet(objeto, taskValue,              // RUN #S151P005 [T005]
                     "S151/TASKFILE/%s/{fecha}/{hhmmss}".formatted(paso)), tx)  // FILE TASKFILE
            .startLimit(3)                     // ON RESTART, GO PASO005: se reintenta desde el inicio
            .listener(new ForzaListadoListener("S151/LIST/" + paso))           // BACKFORZA005
            .build();
}

/** BACKFORZAnnn: el listado se imprime tanto si el paso termina como si falla. */
public class ForzaListadoListener implements StepExecutionListener {
    private final String listado;
    @Override
    public ExitStatus afterStep(StepExecution step) {
        impresion.forza(listado);              // RUN SYSTEM/FORZA("S151/LIST/P005")
        return step.getExitStatus();
    }
}

/** Reemplaza FALLA(PNN): la decisión deja de ser un ACCEPT de consola sin tiempo límite. */
public enum DecisionFalla { REINTENTO, CONTINUA, TERMINA }

# application.yml
s151.lote.politica-falla:
  default: TERMINA
  pasos: { P612: CONTINUA, P005: REINTENTO }    # a definir con Operación

@Component
@RequiredArgsConstructor
public class PoliticaFallaDecider implements JobExecutionDecider {
    private final PoliticaFallaProperties politica;
    private final Impresion impresion;

    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution paso) {
        if (paso.getStatus() != BatchStatus.FAILED) return FlowExecutionStatus.COMPLETED;
        return switch (politica.para(paso.getStepName())) {
            case CONTINUA  -> new FlowExecutionStatus("CONTINUA");      // GO BACKFORZAnnn y sigue
            case REINTENTO -> FlowExecutionStatus.STOPPED;              // reinicio vía JobOperator.restart
            case TERMINA   -> {
                impresion.forza("S151/LIST/" + paso.getStepName());     // RUN SYSTEM/FORZA
                yield FlowExecutionStatus.FAILED;                       // GO FIN
            }
        };
        // La opción V del WFL pide un número de MTP pero no lo asigna: equivale a R.
    }
}

@Bean
Job loteS151(JobRepository repo, ComandoLoteDecider comando,
             Flow diarioFlow, Flow admovFlow, Flow prodiaSateliteFlow,
             BitacoraLoteListener bitacora) {
    return new JobBuilder("S151-WFL-LOTE", repo)
            .listener(bitacora)                    // DISPLAY "INICIA" / "TERMINA" + MYJOB(NAME)
            .start(comando)
                .on("DIARIO").to(diarioFlow)
            .from(comando).on("ADMOV").to(admovFlow)
            .from(comando).on("SATELITE").to(prodiaSateliteFlow)
            .from(comando).on("BAJA").end("SISTEMA DADO DE BAJA")
            .from(comando).on("INVALIDO").fail()   // ELSE: PARAMETRO INVALIDO
            .end()
            .build();
    // En el WFL el ELSE regresa al MENU de consola; en el destino la ejecución
    // termina en FAILED con el parámetro en la bitácora y el operador la relanza.
}
